/** One line about a report, from its note's `comment:`. An admin's Earlier tab only. */
export const FEEDBACK_NOTE_COMMENTS: Readonly<Record<string, string>> = {
  "spya-a40t70": "\"Why are you reading this?\" is now at the top and grows; About you is offered if empty; a big green tick and Open at top and bottom say it is done; PDFs show a bar of sections read. Time-left is queued.",
  "spya-a48229": "On dev. Recording starts the moment the microphone opens, on every browser; on Chrome and Edge it used to start a second late, losing your first words. While it is still opening, the line under the box says \"Wait — opening the microphone…\".",
  "spya-a5gzb9": "Shipped. Since 2026-10-08 a failed import's Report this also carries the address, file name and error, and every import is kept on record so we can debug it later.",
  "spya-a63vmt": "Shipped. In Chat, type @ to bring in one of your own articles, archived and public included; citations of it open it at the passage. Other people's articles are not included.",
  "spya-ah5ws6": "On dev. Every spine card ends in a key to what the spine is and the colours on it now. Search marks already paint the spine and follow the threshold. Other modes painting it: none for now (Greg, q-je2p9y).",
  "spya-ahvk74": "Adding an article someone has already made public now stops and asks: read their copy free, or add your own, which uses one article. You chose to keep the free copy read-only for now (q-c75pj9).",
  "spya-an90k0": "Sending was there but drawn faint, as a disabled button at 45%, which on an iPad may not paint at all. It is now drawn at full strength while it works, and Send reply too. Tell us if your iPad still shows nothing.",
  "spya-aqnz99": "Chat and Explore now offer to add a lasting instruction to About you, as a card you press. Still queued: the same in Learn, and making a saved \"brief\" give answers that are really brief.",
  "spya-ar65p3": "Shipped: a sideways iPhone no longer enlarges a band's text, and, on your answer, the kinds of line that recur across modes now share six named sizes (on /design, under Text roles).",
  "spya-as0et6": "The button that sends is green and the one that backs out is red, in Feedback and now across the app (sharing, Metadata, the admin pages, chat, notes and more). It is a design rule in controls.md.",
  "spya-ast8cu": "Profile → Settings now has Brightness (down to about a fifth of the light) and Text size (up to 137%, everything in proportion), both kept on this device. Please try them on the iPad app once deployed.",
  "spya-axbxr8": "Thirteen more wordmark animations, on dev and not yet deployed: seven for the spider, six for the letters, picked from about fifty ideas from four directions, GPT Sol's among them. Twelve also play on the article loading screen.",
  "spya-ay3u4w": "On dev: four orders, a prioritised default with Glossary's threshold, Find more, and the full width of the band. Untried with a real model until the AI key resets on 1 Nov, so the 0.10 bar is Glossary's and not yet tuned.",
  "spya-az6puq": "Both on dev. A dictation of a second or so is now transcribed (it used to need two). Stop now waits 300 ms for a second press with nothing on screen changing, so a double press lands and sends once the words arrive.",
  "spya-bbe74w": "Needs a decision is now threads: a contents, one thread at a time with a reply box, Defer for now, the ids, your report shut, a shortcut beside the tabs. Check the reply box on your iPhone.",
  "spya-bq9wv5": "Chats now introduce each person or work they bring in, where they name it: about half as many unexplained names for a general reader. Experts saw no change yet; that half is queued.",
  "spya-btjtbb": "Mostly Apple's: an iPhone home-screen app forgets the grant on every restart and 10 minutes after dictation. We fixed one extra prompt of ours. Try Safari's per-site Microphone: Allow; WebKit bug 280394 tracks the rest.",
  "spya-bvzavw": "In a Needs a decision thread the dialog's footer now reads Close · ‹ Previous · Next ›, so the next thread is one press from where you finish replying; and Write's Send is green, like Send reply, while Cancel and Close stay grey.",
  "spya-bynh22": "Our button now docks at the top or bottom edge, away from the iPhone's menu. Hiding the iPhone menu isn't possible from a web page. Please try it on your phone once deployed.",
  "spya-bzwzfw": "Needs a decision is now threads: a contents, one thread at a time with a reply box, Defer for now, the ids, your report shut, a shortcut beside the tabs. Check the reply box on your iPhone.",
  "spya-c09nnb": "One cause for both. The model copied a line number into a section's id, and that one slip threw away the whole Structure, so every mode refused. Now the slip is read as its line, and a bad section is folded into its neighbour.",
  "spya-c0va9e": "More now stands straight after Skim, at the end of its group. On a phone with Diagram showing that place is off the edge, so More moves to the front of the group there, as it did before 2026-10-11.",
  "spya-c2qmbg": "Shipped: Citations and Debate are one mode, now called Sources (your answer B), renamed all the way down, with Bibliography, Reception and Claims, out of Experimental. Old links still land.",
  "spya-c5gvp0": "Where it sits opens on a summary box (overview, its chat, a count per kind), then the findings folded by kind, the most worrying open. The tools moved up as Go further: buttons, each saying what it opens and costs.",
  "spya-c8z66b": "Built as Greg chose (1B, 2A to q-z27hq2): the model may put a figure between quotes in Gist, More and Most, with a cue. Visitors to a shared article walk the figure stops too since 2026-10-18 (A to q-gq0f4k, plan 261018m).",
  "spya-caue42": "Shipped: Reception and Claims, and the claims picker you chose: Claims lists the claims, you tick some or type your own, and one search checks them. Visitors to a shared article see the claims, not your checks (your answer A).",
  "spya-cf30ac": "The details page says \"You own this article\" or \"You don't own this article\". As admin you also see whose it is on a public or private-link article, and since 21 October who opened its private link.",
  "spya-cfbp0q": "Pasting \"Name <email>\" into a voucher's address box now keeps the address and fills an empty name. Several vouchers to one person always added up; a test now holds it, and the form says when an address already has gifts.",
  "spya-cnbv8f": "Shipped: your Earlier tab now sorts reports into Open, Needs a decision, Set aside and Shipped, numbers each one, and lets you answer my questions in place.",
  "spya-cqg70c": "Structure now has its own row under Metadata › AI processing, and Structure › Run again in the command bar. On this paper it can build the deeper tree once the change is deployed and the AI key resets on 1 November.",
  "spya-cwb56b": "An agent can now draft a gift for any article on your shelf; your Send makes the private link. From ChatGPT or Claude on the web, your admin account can also make an article public or take its private link without a press (your C, then A).",
  "spya-d0pyzt": "The More button now stands in the same place in the bottom bar whether Experimental features is on or off, straight after Skim. Diagram, the experimental mode that used to push it along (and on a phone, to the front), now comes after it.",
  "spya-d5e2jk": "A model lists them first, then code adds what it missed; here the call stopped at 70 of 243. Code now reads comma-separated lists too (214 of 243). More model calls for footnotes: question for you.",
  "spya-ddpn5x": "Set aside: researched and planned, not built. It would take about 6 to 9 weeks and needs OpenAI to let us in first. You said it is out of scope for now (2026-10-01).",
  "spya-dk4tfq": "On dev. Reception opens as an outline: the AI's key sources and themes folded, Every page open with two-line rows. New Sources › Investigate: suggested questions and your own, each sent to Chat with a web search.",
  "spya-dkddku": "Pasting \"Name <email>\" into a voucher's address box now keeps the address and fills an empty name. Several vouchers to one person always added up; a test now holds it, and the form says when an address already has gifts.",
  "spya-dktkem": "Poems quoted in a PDF now keep their lines. The Order of Time needs a Refresh to pick it up (the chunk reads are reused, so it costs nothing). Verse the PDF reader typed as paragraphs is queued.",
  "spya-drbkvc": "Recall and Tutorial now search the web when you ask where a piece stands, and Chat and Learn open a link you paste. The guide now searches too, through a small helper (12 October); whether it may open pages is asked in q-madusw.",
  "spya-dxufdw": "You chose A on 2026-10-05: reading time came out from behind Experimental features, for every owner. A switch to turn it off and a way to erase it are not built yet.",
  "spya-e23tee": "Your place in each of your articles is now kept on the server too, so a browser that has never seen the article opens at the paragraph you reached elsewhere, not at the top with the guide.",
  "spya-e2vxrw": "One cause for both. The model copied a line number into a section's id, and that one slip threw away the whole Structure, so every mode refused. Now the slip is read as its line, and a bad section is folded into its neighbour.",
  "spya-e5477u": "Shipped: a small pie after the read time says started, about half, most or finished. You said yes to the shelf too, and each card on your shelf now shows it.",
  "spya-e5t77w": "Shipped: a long piece's glossary follows its length and takes in names met once, like Torricelli. One question for you on authors of cited books in reviews. The rest of \"explain this\" is written up and queued.",
  "spya-eebnxu": "Shipped: the iPad and every screen with no mouse get the phone's narrow margins and tap-for-icons bar, about three more characters a line in portrait with Marginalia on. The phone is unchanged; two further steps are queued for you.",
  "spya-eqjfgv": "Comments were already left out; the one gap, a short post, is fixed. Keeping them folded away instead is a question for you: comments inside the article would be read by every mode as the author's.",
  "spya-es283p": "Ask the guide about what the article says and it now offers an orange \"Ask in Chat\" button that starts a new Chat with your question. Its next steps sit under a heading and stand out more, and it says about half as much.",
  "spya-evtsag": "Chrome and Edge already show words as you talk. Safari, the iPad and Firefox do not, and every way to add it changes how your voice is sent or risks the iPhone recording, so it is a question for you.",
  "spya-exhqqr": "The hang wasn't reproduced, so the three ways Send could do nothing are closed instead: Send now works while the microphone is on, and a send gives up after a minute. And an unsent report now survives a reload.",
  "spya-eyaf3n": "Sources now sits to the left of Referee in the bottom bar, and in the command bar's list.",
  "spya-ez2vus": "Code now lists author-year citations the model left out (79 of LeCun's 82 missed). The model-side fix waits for model calls after 1 Nov (queued), and one question for you on where those rows sort.",
  "spya-frpy22": "Needs a decision is now threads: a contents, one thread at a time with a reply box, Defer for now, the ids, your report shut, a shortcut beside the tabs. Check the reply box on your iPhone.",
  "spya-ftsqsn": "Shipped: title, authors, abstract, contents, thanks and references found at import and folded to a faint stub with an (i), faint in Structure, for visitors too; the paper shows its authors and year. Older articles stay as they are.",
  "spya-furs26": "Chats now pick the clearest example rather than one from your job by default; your field is still used where it is clearest, or when you ask. Measured: forced examples fell from about 10 in 27 replies to 0–1.",
  "spya-fy05y6": "Ask in chat now reopens the item's chat instead of starting another, the item shows the chat's summary in the button's place, and the button is the chat icon with a card. Quotes and Timeline are still queued.",
  "spya-fytjtf": "Quiz writes itself when you open the margin, and you answer its questions there, typed or by one press of the microphone; answered ones turn a quiet green. Asking whether green should mean right. Model evals wait for 1 Nov.",
  "spya-fzd5nq": "On dev. Help has one box now - typing lists the matching pages, and pressing Ask (signed in) sends the same words to the model, whose answer sits above the matches.",
  "spya-ga6m76": "Shipped on phones and small windows, where the bottom bar slides. One question for you: should it also appear on a full-screen iPad or a laptop, where the bottom bar stays put?",
  "spya-gae0zv": "The guide no longer opens a mode by itself: it suggests one with a button you press. Every chat's typing box is bigger and stands out more, and the suggestion buttons sit in the centre.",
  "spya-gapqbt": "Shipped to dev: a page with no date tag now takes its date from the line under its title, or else its address, and the masthead shows it after a re-read. The fold hiding the header image is queued.",
  "spya-gdbsq2": "Shipped: a Cites line in Marginalia now shows the same card a citation in the text does, buttons and all, and a cut-off line's card shows its whole words. Named in the plan, not built: a count line's card listing its items.",
  "spya-gkmgdd": "Re-import keeping your data was already there (Metadata › AI processing › Whole article › Start again, behind the experimental switch); now the command bar finds it too. The wipe option is a question: q-bjkb37.",
  "spya-gm858u": "spya-nbmce7: Most now always longer than More, and since skim/13 More always longer than Gist too (your answer B to q-vzd2xt)",
  "spya-gqq38u": "Saved now: the opinions are kept with the article and dated, and come back on reload. The rule is in database.md, and the plan lists what else we still throw away (Mirror is the one worth doing next).",
  "spya-gsw9bh": "The library, digest and tutorial are on dev. The fifteen product ideas it surfaced are proposals in the Overseer's queue, waiting on you.",
  "spya-gtzeqm": "Recall now does both, and Learn has three parts. It kept the name Recall; if you'd rather the chip said Tutorial, that is only a label change.",
  "spya-gxbwug": "Rotation fixed: the page can no longer be wider than the screen mid-turn, which is what made Safari zoom out. The keyboard case is queued; if it recurs, open the article with ?probe=1 and send the trace.",
  "spya-h2d3my": "Both Needs a decisions now show one number, the questions waiting on you, so one you have replied to or deferred no longer counts. A report's row says Waiting.",
  "spya-h5aypq": "Researched what a peer reviewer needs and drew the line between Sources and Referee; the guide offers Referee to referees. You answered q-fkq30v: Promises and starter criteria are queued first.",
  "spya-h5mteu": "Chat, Recall, Tutorial and Quiz now say when the article is wrong or disputed, in a separate sentence marked as from memory or with a link. Live and Explain are queued to get the same.",
  "spya-hdde62": "The More button now sits straight after Summary in the bottom bar, before Skim, on every screen. On a phone it stays there too, rather than jumping to the front.",
  "spya-hdeye3": "Chat now gives a detailed answer when you ask for one, about twice as long as before, while ordinary answers stay as brief as they were.",
  "spya-hnw9xq": "Summary now links the passage that argues each point, not the abstract or executive summary. And, per your answer B, executive summaries and the other front summaries now fold like the abstract (this article: once re-imported).",
  "spya-hqffdq": "Same bug as #718: Figure 5 still shows the small Earth icon because this article's figures were chosen before that fix. Fixed on dev and deployed; re-importing the article will re-decide its figures (your call).",
  "spya-hrfj6q": "The Referee error was a stored failure from 5 September, before the 28 September fix; a retry works now. The same overflow was live in Search on long papers, and that is fixed.",
  "spya-hrx8z2": "Done. All 11 asterisk notes in your copy of The Order of Time now link both ways. It was refreshed on 25 October, and the 7 minutes of reading time moved with it.",
  "spya-ht4hf4": "On dev. Every chat on an article now answers on Claude Opus 5.5, whatever the article's High-powered AI switch says. Candidates and the tools a chat calls still follow the switch.",
  "spya-hwdefp": "You chose A on 2026-10-05: the private link is built (stage 1). Stages 2 and 3, comments for people with the link and named email addresses, are written up and not built (qi-6jwj562v and qi-mgxnj233).",
  "spya-j4sg9g": "None of your three replies was lost. Once an agent acted on a reply, the dialog hid it and drew the question as never answered. Now it lists them, marked acted on. Whether to sharpen the rule for closing questions is asked in q-jpy4xv.",
  "spya-j5f7yv": "Set aside as someday-maybe: a design was written, but it would have cost the owner the tailoring of their own summaries, and you chose to keep everything personalised (2026-10-01).",
  "spya-j5h3cb": "Both on dev. A dictation of a second or so is now transcribed (it used to need two). Stop now waits 300 ms for a second press with nothing on screen changing, so a double press lands and sends once the words arrive.",
  "spya-jk0xw5": "Shipped to dev: an article's own table of contents now folds to a \"Contents\" stub even when its heading was lost or never there, if its lines link to the article's later sections. This article gets it when re-read.",
  "spya-jvsv3q": "Shipped: a Chat icon under a finished mark opens a new chat with the question, the mark and your answer quoted, ready for you to type. Since 2026-10-24 the question also remembers that chat and reopens it.",
  "spya-jxwfah": "The AI's words now use a face that reads more easily as paragraphs, iA Writer Quattro, in place of the strict monospace. There is no font setting; one face per kind of text, for everyone.",
  "spya-jyjph5": "Not built, for now. Nothing about a Help question is stored today, and the privacy page promises so. A history needs a new table, saved answers, a dated list and a reworded privacy page: about a day's work. The plan has the outline.",
  "spya-k06kam": "Built. View as on /admin/users (and View as owner on /admin/articles) opens the app as that reader sees it, read-only, for 30 minutes after a reason, with a bar and Stop. The privacy page says so.",
  "spya-k49y3q": "Shipped on phones: the column is gone, and a tap brings the icons up in a bar above the paragraph. Still queued for you to decide: whether the iPad should get the same.",
  "spya-k8mka5": "/admin/articles and the Given table on /admin/vouchers now use the same table as /admin/users: sort by any header, hide columns, first column held. Library: TanStack Table, already ours; the v9 upgrade is queued.",
  "spya-kan788": "\"Why are you reading this?\" is now at the top and grows; About you is offered if empty; a big green tick and Open at top and bottom say it is done; PDFs show a bar of sections read. Time-left is queued.",
  "spya-kaxamm": "On dev, behind the experimental switch. Structure's third chip, Hover, looks like Fisheye, but resting the mouse on a row in either column goes there, with no click and no tooltip cards. Or open ?structure=hover.",
  "spya-kbzzk8": "No change at the time: dictation was not on Whisper but on a Gemini model chosen in a bake-off the day before, because it takes the custom vocabulary. The evidence did not justify a swap.",
  "spya-kmqd7n": "On dev. /admin/feedback has a third filter, Admins only, beside Everyone and Readers only.",
  "spya-krvuc9": "Needs a decision is now threads: a contents, one thread at a time with a reply box, Defer for now, the ids, your report shut, a shortcut beside the tabs. Check the reply box on your iPhone.",
  "spya-kwcn4x": "On a tall screen our button was docked at the far edge, up to 600px from your words. It now sits just past the iPad's own menu. Please try it on your iPad once deployed.",
  "spya-kx8z6d": "Both are now in an (i) beside the File button: the file limits, and, after your answer to q-p6fvep, the line saying the text goes to a model provider. The add box has no small print left.",
  "spya-m2pyfq": "The error couldn't be found: it happened in your browser before anything was uploaded, and nothing there reported to Sentry. Now every dictation failure does, and a refused microphone says so instead of \"press it again\".",
  "spya-m40r6t": "Figure 12 and six others were lost to our rules, not the model; three showed a small Earth icon instead. Fixed on dev; re-import the article after the next deploy. A check with the real model waits for the 1 Nov credit reset (queued).",
  "spya-m53cdk": "Shipped: Open in Sources lands on the work, cited works get checked notes from their abstracts, and one with no note gets a web search for a page that is or looks like its own: 4 to 14 notes of 42 on your paper.",
  "spya-m5gxk9": "On dev. While you scroll, Structure now redraws at most once a second (a click or link still moves it at once), and its rows no longer change when the bottom bar slides away and back.",
  "spya-ma72mx": "Asked for links, the guide now points straight at places in the article. Asked for searches, it offers buttons that run inside the chat and list the passages as links, without switching to Search mode.",
  "spya-mcs4gb": "Skim and More now sit in Structure and Summary's group, and Comments sits with Marginalia, after it. On a phone More is now almost on screen, but the bar still scrolls sideways.",
  "spya-mdmqqq": "You were right, there were two. While an article loads, the centred animated wordmark is now the only one; the corner logo is gone from that screen, before the 600ms threshold and after it.",
  "spya-mdp0em": "Built as you chose (option A). The public shelf now has topic pills, kept up to date by themselves up to 20 shared articles and billed to a site account; past 20, a Rebuild button on the admin page. They appear once 8 articles are shared.",
  "spya-mfuz6g": "Opening Where it sits with the Sources button or its tab now starts the literature search by itself (a link or Back does not). The summary has its own Ask in chat, quotes go to their passage, and cited works link out.",
  "spya-mj4b56": "On dev. Switching to another mode now closes the chat instead of floating it over the next mode. Back brings it back. Switching to Chat, or between sub-modes of the mode you are in, keeps it. Unsent words are kept.",
  "spya-mpg67x": "Asked for links, the guide now points straight at places in the article. Asked for searches, it offers buttons that run inside the chat and list the passages as links, without switching to Search mode.",
  "spya-mq05ww": "Shipped: 22 cropped, captioned screenshots and 3 GIFs across 21 Help pages, and help-page.md says how to keep them true. Eight modes still have no picture; that is queued.",
  "spya-mutgym": "Every \"older version of the article\" notice now has an × that holds until that thing is made again. Quiz's is left: there no answer can be marked, and the notice is the only thing saying why.",
  "spya-mxdf6r": "The JSON was already schema-checked; the model miscopied block ids. Structure now gives each block's number instead, right 20 of 20 times on Adrian's article. Thirteen other steps copy ids too: queued, to measure each.",
  "spya-mxk20e": "Rest on a citation naming one work and after about 2 seconds the card starts Does it say that? and shows its answer: about 20 seconds and 17p each, capped per day. A tap does not start one; the button does. Each is a chat in Chat's list.",
  "spya-n50aft": "Every version of an arXiv paper is now one article, and the shelf you already have matches too. The cost: pasting v2 while you hold v1 gives you v1.",
  "spya-n7hvm0": "Needs a decision is now threads: a contents, one thread at a time with a reply box, Defer for now, the ids, your report shut, a shortcut beside the tabs. Check the reply box on your iPhone.",
  "spya-n8cuqq": "Shipped: dictation runs fifteen minutes and warns before it stops, and Feedback now takes 20,000 characters, a full fifteen minutes of non-stop speech.",
  "spya-nbmce7": "spya-nbmce7: Most now always longer than More, and since skim/13 More always longer than Gist too (your answer B to q-vzd2xt)",
  "spya-nhhd0x": "arXiv papers no longer bring in the TeX LaTeXML could not convert, such as \"\\hohsettheme\" and \"hohRose\". About one paper in nine had some. The article you saw stays as it is.",
  "spya-njkskc": "On dev: explained passages are underlined in the prose in every mode, Glossary's dotted rule in teal, with a card (explanation, labels, Ask in chat, Open in Explanations). A term inside keeps its orange rule. Behind the experimental switch.",
  "spya-nkq6rj": "Explanations are built behind the experimental switch; they join imports after the first live run (1 Nov). The margin button now starts Sources' literature search, first press only.",
  "spya-nnr8ha": "You chose not now (q-wux4k7, 2026-10-08). Browser zoom, Cmd or Ctrl with +, already scales everything, so no setting was built.",
  "spya-np36qf": "Checked: a gift's starter article never uses the recipient's free articles (production agrees), and a test now holds it. /admin/vouchers now opens by saying what a voucher, a starter article and an author gift each are.",
  "spya-nsrkju": "Sharing on the Add page is reshaped and reworded after five persona critiques. The confirmation panel, two privacy sentences and the rest of the page are queued (qi-krppt8r9).",
  "spya-nt6hee": "Each draft now shows the email itself (from, to, subject, body) and an Edit the email button; the notes say they are never sent. Whether the fixed wording around your message should be editable too is my question to you.",
  "spya-p4uqye": "The guide now suggests before it asks, never asks about you, and answers a passage question briefly. It can also get a mode ready in the background (once a conversation, never opening it), and plan Skim from what you said.",
  "spya-p5x9wy": "Shipped: a long PDF costs one article per 50 pages, charged before any transcription, with a warning on import. The cap stays 250 pages for now, because a 400-page maths book failed to import. Raising it to 400 is queued.",
  "spya-p88dcx": "On dev. Metadata › Export has \"Download your notes and conversations\": one Markdown file of everything you wrote on the article, also in the zip. Each conversation's header has \"Copy this conversation as Markdown\", to paste into another AI.",
  "spya-p8h7r3": "On dev. Help's question box now grows as you type, so the whole question stays visible, and goes back to two lines when emptied. It is the same fit the Feedback, Quiz and Add boxes use.",
  "spya-pd9fnc": "Both halves are on dev. Dictation: the microphone button no longer moves when you press Stop, so a quick second tap lands and sends once the words arrive. The Chat half: a \"‹ Chats\" button and the model in the (i).",
  "spya-pdpnjf": "Ask in chat now reopens the item's chat instead of starting another, the item shows the chat's summary in the button's place, and the button is the chat icon with a card. Quotes and Timeline are still queued.",
  "spya-pkpqch": "Once Where it sits has searched the literature, its findings show in Marginalia beside their passage (Challenged, Since, Supported…), Experimental features on or off. Open one for its note and sources.",
  "spya-pn7gvw": "Done as you chose: the level is made automatically, and column B opens the section you are in to show its sub-sections (all three judges picked it). No article has it until after the 1 Nov key reset. Open: re-run this paper then?",
  "spya-pqae7m": "Quotes in Skim, and the article's words wherever a mode shows them, now draw formulas as maths and keep italics, bold and sub/superscripts, as the paragraph does. Links show as plain words there.",
  "spya-pqaftb": "The guide now offers up to three next steps as buttons, and for a private link, sharing or archiving a button that takes you to where you do it. Still to come: sharing in a dialog over the page, and archive on the press (qi-ddvxcsdv).",
  "spya-ptjk63": "The guide now suggests before it asks, never asks about you, and answers a passage question briefly. It can also get a mode ready in the background (once a conversation, never opening it), and plan Skim from what you said.",
  "spya-q2qb7q": "Box health, the worktree sweep and the dashboard refresh are now systemd timers that survive a reboot. You said yes to the feedback sweep timer (q-rh49ck); the Overseer switches it on.",
  "spya-q2w7yt": "spya-nbmce7: Most now always longer than More, and since skim/13 More always longer than Gist too (your answer B to q-vzd2xt)",
  "spya-q3pzyn": "An empty command bar on your own article now starts with Guide chat, marked with a compass, and the compass marks the guide everywhere it appears. The home page has no guide: it belongs to an article.",
  "spya-q645m0": "Profile → Settings now has Brightness (down to about a fifth of the light) and Text size (up to 137%, everything in proportion), both kept on this device. Please try them on the iPad app once deployed.",
  "spya-qawppt": "The Topics row above your shelf now shows six pills, with \"All N topics\" for the rest; the public shelf does the same.",
  "spya-qdd2vc": "Each account on /admin/vouchers now links to /admin/users, which marks that row, and the link's card summarises their usage: sign-ins, shelf, comments, chats, searches, opens, plan and this month's model calls.",
  "spya-qkyukr": "Pasting superdark's front page now imports all four pages as one article (344 blocks, not the 2,246-character abstract). Haiku judges every web page, ~$0.0005 each; nobody is asked.",
  "spya-qpgvq9": "spya-x0rfs2: the bar is fixed; the quieter open stop Greg chose in q-u04sye is on dev as an experiment",
  "spya-qspg5a": "Reopening an article now lands on the paragraph you were reading, on this device, and no longer slips back a section each time.",
  "spya-qtk3q2": "Both sentences now say what happened, and arXiv papers find their DOI, so Attention gets its Cited by list. Since 11 October a piece with no DOI is also looked up at OpenAlex by title and authors, strictly checked.",
  "spya-qxh28e": "Word (.docx), Markdown and text uploads are in. Still queued: pictures from Word files, and .odt/.rtf/.epub/.doc/.tex.",
  "spya-qxufp9": "Declined: one model call writes the article's tree and these summaries together, and Structure, the shelf and hover cards need the tree as soon as the article opens. Deferring them means splitting that stage.",
  "spya-r246pf": "On a phone, Skim now shows every quote in full, so you can read down the route without leaving it. A tapped glossary term should now keep its card open; we could not make it fail off your iPhone, so please tap one after the next deploy.",
  "spya-rbp55k": "The line is said once above the list now. A chat's summary shows wherever Ask in chat has an item to put it on; Summary's paragraph and Quotes, Timeline and FAQ are still queued.",
  "spya-rg5kk6": "Re-read in production on 23 October: the page 43 line, the page 95 passage and notes 21–93 are back. On 24 October your bookmarks and reading time were moved onto the new paragraphs: 6 bookmarks, all in place.",
  "spya-rgh26u": "With Marginalia on, the prose now moves left at every window width so the chat card gets the room. At your size the card went from 282px to 517px. Nothing changes beside a band.",
  "spya-rvj2p7": "Shipped: a short article whose suggested links all pointed at the next paragraph no longer fails; the step is now called \"Adding cross-references\", and a failed extra says the article is unchanged.",
  "spya-s6qhzv": "The guide greets you in the chat, takes Live, has a Guide row in the bar, and offers to save your reason and About you on your press. Since then it also offers buttons for a private link, sharing and archiving (261009u).",
  "spya-s8pf4r": "The marks were already on your paper's two parts but too faint to see; now darker and bigger. Tables were already in Skim's Figures; a table published as a picture now counts as a table too.",
  "spya-s902kr": "Every gift's article now gets its main modes made, and the Give form has a High-powered AI box (on by default). It uses Opus for what is still to be made; whether it should also redo what Sonnet already made is my question to you.",
  "spya-sbj3yk": "Both sentences now say what happened, and arXiv papers find their DOI, so Attention gets its Cited by list. Since 11 October a piece with no DOI is also looked up at OpenAlex by title and authors, strictly checked.",
  "spya-sfpcmm": "On dev. A chat (and Explore) reading another of the reader's conversations now gets each question and answer whole, up to 6,000 characters a turn, rather than cut to 700, and can page back through a long conversation to its first exchange.",
  "spya-shf45w": "On dev: Active days, Reading time and Failed imports columns, and five counts hidden behind Columns. Since your answer, Active days also counts each article opened, from now on.",
  "spya-shpsvx": "The home-screen icon now follows your phone's mode when added: charcoal in dark, cream in light, charcoal when unsure. After the next deploy, remove the icon and re-add it from Safari's Share menu to see it.",
  "spya-shwpw5": "Ideas no longer runs on import; it was about 19¢ an article, the dearest step after Summary. Skim now plans new articles without it. Opening Ideas still makes it.",
  "spya-skpxw2": "Part built: type @ in Chat to bring in one of your articles, so an uploaded file can be brought in once it is an article. Attachments that belong to an article are still a question for you.",
  "spya-skq3fg": "\"Why are you reading this?\" is now at the top and grows; About you is offered if empty; a big green tick and Open at top and bottom say it is done; PDFs show a bar of sections read. Time-left is queued.",
  "spya-srg5fa": "The guide no longer opens a mode by itself: it suggests one with a button you press. Every chat's typing box is bigger and stands out more, and the suggestion buttons sit in the centre.",
  "spya-sshjd2": "Shipped: your Earlier tab now sorts reports into Open, Needs a decision, Set aside and Shipped, numbers each one, and lets you answer my questions in place.",
  "spya-sy4rn0": "Search's toggle is now just words and meaning. A meaning search shows a quick answer in about a second and swaps in the thorough one by itself once you stop typing; old quick links still open it.",
  "spya-t45cfc": "Every /admin table now keeps its first column on screen while it scrolls sideways — Account on /admin/users, Article on /admin/articles, Email on /admin/vouchers, and the label column of all four /admin/costs tables.",
  "spya-t6nmxt": "Needs a decision is now threads: a contents, one thread at a time with a reply box, Defer for now, the ids, your report shut, a shortcut beside the tabs. Check the reply box on your iPhone.",
  "spya-t7cq2s": "On dev. When a Chat answer mentions one of your earlier conversations, the mention is now a link that opens it, in the band or the floating chat; Back returns. Explore is queued to follow.",
  "spya-t858ug": "Live conversation is on GPT-Live for everyone now, with no engine dropdown. With Experimental features on, Realtime is a small arrow on the Live button.",
  "spya-t9qu3v": "The hang wasn't reproduced, so the three ways Send could do nothing are closed instead: Send now works while the microphone is on, and a send gives up after a minute. And an unsent report now survives a reload.",
  "spya-tfp3zw": "The Feedback dialog is bigger again on a large window (56rem wide from 1280px, taller from 900px), and in a Needs a decision thread Send reply is green and Defer for now red.",
  "spya-tfsjvq": "Shipped: the top bar now starts below the clock wherever the phone draws one over it, and is still flush at the top where nothing does. Certain on the home screen; please check a Safari tab after the deploy.",
  "spya-thpsnd": "Shipped: Reception and Claims, and the claims picker you chose: Claims lists the claims, you tick some or type your own, and one search checks them. Visitors to a shared article see the claims, not your checks (your answer A).",
  "spya-tj0vqa": "On dev. Structure's list no longer leaves a ~55px blank strip on its right (room kept for the (i), which sits only in the top row). The prose margin is unchanged: on a touch screen it holds only the paragraph marks.",
  "spya-tqsw3u": "A refused paper link now imports Europe PMC's free full text instead; your cell.com link comes in this way. Otherwise the Save for Spideryarn bookmarklet saves the page to upload, and it keeps its address.",
  "spya-tsd470": "Hovering a reference entry now lists every paragraph that cites it, each a jump. A work cited directly in the text more than three times is found only three times so far; that fix is queued.",
  "spya-tv6wn5": "Dig deeper is gone and Ask in chat stands in its place, on the hover cards too, and now on Ideas. A chat started from an item has a \"Back to …\" line that opens the mode on that item.",
  "spya-twsm7t": "Chat's list now says Investigate (or Claims, Glossary, Quiz…) under each chat started there. A chat from a Quiz mark goes back to its question, and the question shows it.",
  "spya-u3yw2a": "Every typed Chat, Learn, Explore and guide turn starts from shared principles and, when the totals can be read, is told roughly how much of the article you have read.",
  "spya-u5azdm": "The model wrote an invisible NUL while reading three pages of maths, and the database stores none. Such characters now become spaces where text comes in. Once deployed, retry the job; it pays only for those three chunks again.",
  "spya-u6h6q8": "Needs a decision is now threads: a contents, one thread at a time with a reply box, Defer for now, the ids, your report shut, a shortcut beside the tabs. Check the reply box on your iPhone.",
  "spya-u8stc4": "On dev. Every spine card ends in a key to what the spine is and the colours on it now. Search marks already paint the spine and follow the threshold. Other modes painting it: none for now (Greg, q-je2p9y).",
  "spya-uc0asn": "You chose B: a signed-in visitor can add a private copy of a public article to their own shelf and use AI there. AI in place on someone else's article (C, D, E) is not for now, as you said on 2026-10-07.",
  "spya-ucftjt": "All three parts shipped: Help in the bar and as pages, Ask about Spideryarn on the Help pages, and a guide in Chat. The Help chatbot stays signed-in only for now, as you chose.",
  "spya-ufn2xj": "Fixed: Cited by now checks an arXiv paper against arXiv's own record when ours is stale. Production went from 21 to 28 of 28 DOIs confirmed; the one known wrong record (BERT) is still refused. No model call.",
  "spya-um8d9f": "Already fixed: it is Box 3 of the paper (words and its self-attention diagram), the same fault as your report of 24 Oct. The import ran on 17 Oct, before the fix; a re-import brings all four boxes back.",
  "spya-us5kzc": "Set aside: this was a test of the Feedback button on the day it shipped, so there was nothing to build.",
  "spya-v322fd": "You chose A on 2026-10-05: the private link is built (stage 1). Stages 2 and 3, comments for people with the link and named email addresses, are written up and not built (qi-6jwj562v and qi-mgxnj233).",
  "spya-v88mga": "On dev. Type \"gift\" in the command bar while reading your own published article: a dialog over the article drafts the author gift, nothing sent. Also \"what it cost\" and the /admin pages and /design, for the administrator only.",
  "spya-vc6uzm": "The guide searches the web and can now open a web page, as Chat does; and a web page can be brought into a Chat with a button, as an @-mention.",
  "spya-vcnmrd": "Tabs Give, Drafts, Given; one New gift form whose tick-box makes it an author gift; discarded and sent gifts fold to one line with Restore. Not done: deleting them, or merging the two tables underneath. Say if you want either.",
  "spya-vfk2zh": "Replaced. Affiliations now come from one cheap Haiku call on any site, held to the page's words: same as before on 9 of 13 arXiv papers, better on 2, wrong on none, ~$0.0005.",
  "spya-vgwt4z": "No change: the Send button already had a spinner, in production since 2026-09-01, and a test now pins it. You decided against adding a minimum time on screen (2026-09-06).",
  "spya-vh0z7s": "You chose to keep Reception and Claims as two sub-modes, with the clearer Claims card already built (q-hbg65m 1A). And Cited by now finds a piece with no DOI by its title and authors at OpenAlex (2C).",
  "spya-vm5enm": "Built. View as on /admin/users (and View as owner on /admin/articles) opens the app as that reader sees it, read-only, for 30 minutes after a reason, with a bar and Stop. The privacy page says so.",
  "spya-vqpeyr": "On dev. In Structure's two columns, the part you are in now flows into column B as one grey Sankey-style band, from that row's height to the whole of column B. The switch to two columns did not move.",
  "spya-vusqvg": "Tabs Give, Drafts, Given; one New gift form whose tick-box makes it an author gift; discarded and sent gifts fold to one line with Restore. Not done: deleting them, or merging the two tables underneath. Say if you want either.",
  "spya-vuw2hy": "Checked: a gift's starter article never uses the recipient's free articles (production agrees), and a test now holds it. /admin/vouchers now opens by saying what a voucher, a starter article and an author gift each are.",
  "spya-vx23nt": "With no DOI, Sources now lists Possible citations: free, papers whose text matched the title (Experimental features; ~4 in 5 really cite it). Your web search with a model judging each page is designed, waiting on the AI key's 1 Nov reset.",
  "spya-vyddks": "Tabs Give, Drafts, Given; one New gift form whose tick-box makes it an author gift; discarded and sent gifts fold to one line with Restore. Not done: deleting them, or merging the two tables underneath. Say if you want either.",
  "spya-vywcpu": "You counted right: 70. Now about 60 a line (at most ~65 on nine lines in ten) at every text size. Phone margins were already minimal. Your middle for q-z3j0ep: Marginalia notes 56px closer, iPad-landscape band 400 → 486.",
  "spya-vzj8fc": "A recording left on one article is no longer offered on another; Chat, passage chat and the command bar had the same gap, all fixed. The microphone now has a card: why talk, the 15-minute limit, and press Stop twice.",
  "spya-w95xmq": "Sources is now three chips. Where it sits opens on free lists; \"Search the literature\" (~$0.30, Haiku shortlist then Sonnet) starts when you press to open it, and has left the experimental switch. Two experiments behind it.",
  "spya-w99qsz": "Shipped: the margin says where a quote or allusion comes from (marked AI memory, unchecked), and a cited work opens to what its abstract says. Queued: does it say what they claim, Explanations, Sources widened, debate in the margin.",
  "spya-wc4vku": "Both add-page boxes now have a microphone, and the page waits while you dictate. So do Skim's purpose, Referee's criterion, the Candidates scope and a comment's note. controls.md says so; a test fails on any new writing box without one.",
  "spya-wembb7": "On dev. Feedback did not remember anything: you dictated there 10 seconds after a chat dictation. Every press now asks inside your tap, so an iPad should ask once per sitting, until 10 minutes idle or an app restart.",
  "spya-weuekx": "Shipped for web articles; the empty \"figure\" was Box 1 of the paper, and all four boxes now import. A PDF's tables don't get the link yet (queued, qi-zbpqb2r9). This article changes only if re-imported.",
  "spya-whpceg": "No chat tool, as your addendum said. This paper's title is already right on a fresh import (fix deployed 10-18); it needs re-extracting. Also fixed: arXiv titles with a line break lost a space or their part before the colon.",
  "spya-wm5gu2": "Skim and More now sit in Structure and Summary's group, and Comments sits with Marginalia, after it. On a phone More is now almost on screen, but the bar still scrolls sideways.",
  "spya-wqvxjv": "A draft gift now has its own address for the agent to open; a private gift article becomes the recipient's when they sign in; /admin/articles moves any article. Titles of other readers' articles stay hidden there.",
  "spya-wu83xh": "Shipped: a skim-for box (your purpose, edited in Skim), a map line per pass (visitors see it too, your A to q-t5xjqn), shorter stops. Per-stop linking lines and a Skim-only focus are queued.",
  "spya-wwyw8y": "For an admin, every Feedback button now shows a small red number when threads need a decision, the same number as Needs a decision inside. Readers see nothing new and make no extra request.",
  "spya-x0rfs2": "spya-x0rfs2: the bar is fixed; the quieter open stop Greg chose in q-u04sye is on dev as an experiment",
  "spya-x38nge": "The guide greets you in the chat, takes Live, has a Guide row in the bar, and offers to save your reason and About you on your press. Since then it also offers buttons for a private link, sharing and archiving (261009u).",
  "spya-x4zujq": "On dev: the feedback rules now treat a reader's suggestion as evidence, not authority, and anything other readers would notice is built only if Opus and GPT Sol both back it, else it comes to you.",
  "spya-x5e966": "A refused paper link now imports Europe PMC's free full text instead; your cell.com link comes in this way. Otherwise the Save for Spideryarn bookmarklet saves the page to upload, and it keeps its address.",
  "spya-x6qjbn": "There's no clean-up prompt to tweak, and the transcriber ignores a paragraph instruction (tested). You chose to leave dictation as one paragraph rather than add a second step (q-a0qp3x, A).",
  "spya-x9gn3d": "Uncaptioned PDF figures are now kept, and their pictures found by the sentences either side of them (25 of 28 on Rovelli, locally). Re-importing your Rovelli article is queued for after the deploy (qi-vq9rwkyy).",
  "spya-xasbd3": "The bar shows at most four suggestions, each can be dismissed for good with × or Delete, the list folds to one line, and on an empty box Guide is the first row.",
  "spya-xcmg2d": "Help's Ask box has the same microphone as every other box. Every mode's Help page now opens with a short \"why care, what for, how it works\", then a picture of it in use. Annotated pictures skipped, as you suggested.",
  "spya-xdvnrg": "A recording left on one article is no longer offered on another; Chat, passage chat and the command bar had the same gap, all fixed. The microphone now has a card: why talk, the 15-minute limit, and press Stop twice.",
  "spya-xg4jyr": "New arXiv imports show one tidy row per author, and each name's affiliation on hover. Your Attention import is re-imported after the next deploy, as you asked.",
  "spya-xn4597": "The figures did import; the four colour grids came out as broken tables. The prompt now names the cell separator. The sliced cover photo is queued as qi-r6f9s4f9, waiting on you.",
  "spya-xsfrsg": "In the Chrome Web Store (Unlisted) and wired into production. Help, the command bar and a refused import now point to it. Still to come: select a passage and arrive in a chat about it.",
  "spya-xurkmf": "Your words are now in Kalam, a pen hand, on dev. One question for you (q-t9ub4x): keep Kalam, or one of the calmer runners-up, Delius or Klee One?",
  "spya-xv3q97": "Ask in chat on a cited work now quotes the sentences where the article cites it, and asks first what point the article uses the work to make and whether the work supports that, then for the outside background.",
  "spya-xyje0z": "Skim holds several briefs per article. A ▾ on the \"Reading for\" line switches between them, and adds, edits or deletes one; each gets its own route. Real routes for added briefs can be planned once the key resets on 1 November.",
  "spya-y43ha0": "On dev: a question about a reader's report shows it in its thread, marked as a reader's. The per-reader cap stays at 30 an hour, and agents now settle low-stakes questions like that one themselves.",
  "spya-y4yhnp": "Under a finger, each web source is now one block (its button under its own title, a line between sources), and nearly everything you can press is 40px. Left for you: whether the gutter's bar may cover two lines.",
  "spya-y5gfpf": "Help's Ask box has the same microphone as every other box. Every mode's Help page now opens with a short \"why care, what for, how it works\", then a picture of it in use. Annotated pictures skipped, as you suggested.",
  "spya-yf23zk": "The bar shows at most four suggestions, each can be dismissed for good with × or Delete, the list folds to one line, and on an empty box Guide is the first row.",
  "spya-yjnpjg": "Backspace now presses the \"back to ⟨section⟩\" chip while it is on screen. It does nothing in a text box or while a dialog is open, and the chip shows a small ⌫.",
  "spya-yk3r03": "The guide updates your profile and reason; your exact typed words, or one whole sentence of them with only the spelling tidied, save by themselves with an Undo. You chose to keep the rewording light for now (q-tz5az8).",
  "spya-yt2v73": "The guide now suggests before it asks, never asks about you, and answers a passage question briefly. It can also get a mode ready in the background (once a conversation, never opening it), and plan Skim from what you said.",
  "spya-yyc7te": "Every typed Chat, Learn, Explore and guide turn starts from shared principles and, when the totals can be read, is told roughly how much of the article you have read.",
  "spya-z30x5n": "Each chat message now records how it was made: a question as typed, dictated, mixed or spoken, an answer as written or spoken. So live-voice answers can be reviewed. The command bar's \"Ask the guide\" box is still queued (qi-9pknjrsf).",
  "spya-z3uz86": "Measured, and no: smaller chunks were not reliably faster and cost about 15% more, because twice the chunks meant twice the re-asks. The speed-up is in those re-asks, which are queued.",
  "spya-za2tse": "Needs a decision is now threads: a contents, one thread at a time with a reply box, Defer for now, the ids, your report shut, a shortcut beside the tabs. Check the reply box on your iPhone.",
  "spya-za4bxk": "On dev. Recording starts the moment the microphone opens, on every browser; on Chrome and Edge it used to start a second late, losing your first words. While it is still opening, the line under the box says \"Wait — opening the microphone…\".",
  "spya-zdkqx4": "spya-x0rfs2: the bar is fixed; the quieter open stop Greg chose in q-u04sye is on dev as an experiment",
  "spya-zh5f23": "On the shelf the add box is now the wider card on the left, with a heading and a link icon, and the search box is narrower and on the right; a link pasted into the search box offers to add it.",
  "spya-zjsqe6": "The Feedback dialog is bigger again on a large window (56rem wide from 1280px, taller from 900px), and in a Needs a decision thread Send reply is green and Defer for now red.",
  "spya-zt7u0h": "That article is yours: its PDF import failed this morning on the NUL bug, since fixed. Your own failed import now shows its card with Retry instead of Not shared, and the table says Not published rather than Untitled. Press Retry.",
  "spya-zuk4f7": "Both stages shipped: Debate asks for work that cites the piece, and OpenAlex supplies its count and list of citing papers.",
  "spya-zux9w6": "The citation, glossary and quote cards now each end in Open in Sources / Glossary / Quotes. Cards on comments, chat anchors and search-style highlights are queued as their own piece of work.",
  "spya-zytb0g": "Built: a Discussion kind for you, monospaced ASCII in questions, and mockups that open inside this dialog. ASCII is the default for now, as you chose; the Overseer's rules reworded (1A).",
  "spya-zz4z4c": "Every \"older version of the article\" notice now has an × that holds until that thing is made again. Quiz's is left: there no answer can be marked, and the notice is the only thing saying why.",
  "spya-zzewu7": "Every /admin table now keeps its first column on screen while it scrolls sideways — Account on /admin/users, Article on /admin/articles, Email on /admin/vouchers, and the label column of all four /admin/costs tables.",
  "spya-zzvm6e": "The marks were already on your paper's two parts but too faint to see; now darker and bigger. Tables were already in Skim's Figures; a table published as a picture now counts as a table too.",
};
